{"cards": [{"node_code": "N_fe7d79eab0e9bba7", "definition": "指结构可移动、可折叠或随环境条件改变形态的临时性道路设施，包括活动便道、变形路基及可拆卸式路面系统，用于应对特殊地形或短期运输需求。", "boundary": "本节点聚焦于“结构可变”或“临时性”的道路设施。边界在于区分“活动变形道”与“固定式特种道路”（如林区、矿区固定道路）；区分“活动变形道”与“常规道路养护”（本节点侧重结构本身的变形与移动特性，而非路面修补）。若内容涉及可移动桥梁或临时便桥，归入本节点；若涉及固定式活动板桥，需视其是否具备长期固定属性，通常归入桥梁工程或本节点。", "includes": ["活动便道、临时变形路基的设计与施工", "可折叠、可拆卸式路面材料及结构技术", "用于应急、军事或特殊作业环境的移动式道路设施"], "excludes": ["固定式的林区、矿区或军用道路工程", "常规公路的养护、修补与加固技术", "大型固定式桥梁或隧道工程"], "sibling_distinctions": [{"other_code": "N_c6ac6cf5362d62f7", "rule": "区分依据为结构特性：活动变形道侧重结构的可移动、可变形或临时性；冰雪道路侧重在冰雪环境下的固定或半固定路面工程。"}, {"other_code": "N_dcb71408ba5fd0f8", "rule": "区分依据为用途与固定性：活动变形道多为临时或移动设施；林区道路多为服务于林业生产的固定专用道路。"}, {"other_code": "N_e6003e7f555efcdb", "rule": "区分依据为用途与固定性：活动变形道多为临时或移动设施；矿区道路多为服务于矿山开采的固定专用道路。"}, {"other_code": "N_f60135d4f7e9b9dd", "rule": "区分依据为用途与固定性：活动变形道侧重结构变形与临时性；军用道路侧重军事战略与战术需求的固定或半固定道路系统。"}], "cross_boundary_rule": "若内容涉及在冰雪环境中使用的活动变形道，侧重结构变形与移动特性归本节点，侧重冰雪路面材料与技术归冰雪道路。"}, {"node_code": "N_c6ac6cf5362d62f7", "definition": "指在冰雪覆盖或极寒环境下修建、维护及使用的道路系统，包括冰雪路面工程、防滑技术、除雪除冰设施及极地运输道路规划。", "boundary": "本节点聚焦于“冰雪环境”下的道路工程与运营。边界在于区分“冰雪道路”与“常规道路冬季养护”（本节点侧重冰雪作为主要路面材料或极端环境下的专用道路，而非普通公路的冬季除雪）；区分“冰雪道路”与“活动变形道”（本节点侧重环境适应性，活动变形道侧重结构可变性）。若内容涉及冰面道路、雪道或极地公路，归入本节点。", "includes": ["冰雪路面材料、结构设计与施工技术", "极寒环境下的道路防滑、除雪除冰技术与设备", "极地、高海拔冰雪地区的道路规划与运输组织"], "excludes": ["常规公路在普通冬季条件下的除雪养护作业", "非冰雪环境下的特种道路（如林区、矿区道路）", "活动变形道等临时性结构设施（除非特指冰雪环境下的变形道）"], "sibling_distinctions": [{"other_code": "N_fe7d79eab0e9bba7", "rule": "区分依据为环境 vs 结构：冰雪道路侧重冰雪环境下的路面工程；活动变形道侧重结构的可移动或变形特性。"}, {"other_code": "N_dcb71408ba5fd0f8", "rule": "区分依据为环境 vs 用途：冰雪道路侧重冰雪环境；林区道路侧重林业生产用途，即使林区有冰雪，若侧重林业专用属性归林区道路。"}, {"other_code": "N_e6003e7f555efcdb", "rule": "区分依据为环境 vs 用途：冰雪道路侧重冰雪环境；矿区道路侧重矿山开采用途。"}, {"other_code": "N_f60135d4f7e9b9dd", "rule": "区分依据为环境 vs 用途：冰雪道路侧重冰雪环境；军用道路侧重军事用途。"}], "cross_boundary_rule": "若内容涉及在冰雪环境中使用的活动变形道，侧重冰雪路面材料与技术归本节点，侧重结构变形与移动特性归活动变形道。"}, {"node_code": "N_dcb71408ba5fd0f8", "definition": "指服务于林业生产、木材运输及林区管理的专用道路系统，包括林区公路、木材集材道、防火道及林区道路规划、设计与养护技术。", "boundary": "本节点聚焦于“林业用途”的专用道路。边界在于区分“林区道路”与“常规公路”（本节点侧重林区内部或服务于林业的专用道路，而非连接林区与外界的公共公路）；区分“林区道路”与“其他特种道路”（如矿区、军用道路，依据服务对象区分）。若内容涉及林区道路在特殊地形（如山地、沼泽）下的工程，归入本节点。", "includes": ["林区公路、木材集材道、防火道的设计与施工", "林区道路规划、养护及运输组织技术", "服务于林业生产的专用道路基础设施"], "excludes": ["连接林区与外界的常规国道、省道或高速公路", "非林业用途的特种道路（如矿区、军用、冰雪道路）", "林区内的非道路基础设施（如林业机械、通信设施）"], "sibling_distinctions": [{"other_code": "N_fe7d79eab0e9bba7", "rule": "区分依据为用途 vs 结构：林区道路侧重林业生产用途；活动变形道侧重结构的可移动或变形特性。"}, {"other_code": "N_c6ac6cf5362d62f7", "rule": "区分依据为用途 vs 环境：林区道路侧重林业生产用途；冰雪道路侧重冰雪环境下的路面工程。"}, {"other_code": "N_e6003e7f555efcdb", "rule": "区分依据为服务对象：林区道路服务于林业生产；矿区道路服务于矿山开采。"}, {"other_code": "N_f60135d4f7e9b9dd", "rule": "区分依据为服务对象：林区道路服务于林业生产；军用道路服务于军事需求。"}], "cross_boundary_rule": "若内容涉及林区内的冰雪道路，侧重林业专用属性归本节点，侧重冰雪路面通用技术归冰雪道路。"}]}
